"""Overdue fee statements: python3 fees.py INPUT_DIR OUTPUT_FILE"""
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP

DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]


def read_text(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return f.read()


def read_csv(path):
    text = read_text(path)
    rows = []
    for row in csv.DictReader(text.splitlines()):
        rows.append({(k or "").strip(): (v or "").strip() for k, v in row.items() if k is not None})
    return rows


def cents(s):
    return int((Decimal(s.strip()) * 100).to_integral_value(rounding=ROUND_HALF_UP))


def pnum(s):
    d = re.sub(r"\D", "", s or "")
    return int(d) if d else 0


def parse_offset(s):
    m = re.fullmatch(r"([+-])(\d{1,2}):?(\d{2})", s.strip())
    sign = -1 if m.group(1) == "-" else 1
    return sign * (int(m.group(2)) * 60 + int(m.group(3)))


def parse_policy(path):
    sections = {}
    cur = None
    for line in read_text(path).splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("[") and line.endswith("]"):
            cur = line[1:-1].strip()
            sections.setdefault(cur, {})
            continue
        if "=" in line and cur is not None:
            k, v = line.split("=", 1)
            sections[cur][k.strip().lower()] = v.strip()
    return sections


def d2(s):
    return date.fromisoformat(s.strip())


def main(indir, outfile):
    pol = parse_policy(os.path.join(indir, "policy.ini"))
    st = pol["statement"]
    library = st["library"]
    pstart = d2(st["period_start"])
    pend = d2(st["period_end"])
    clock = pol.get("clock", {})
    base_off = parse_offset(clock.get("offset", "+00:00"))
    changes = []
    for part in clock.get("changes", "").split(";"):
        part = part.strip()
        if not part:
            continue
        inst, off = part.split()
        t = datetime.strptime(inst, "%Y-%m-%dT%H:%MZ").replace(tzinfo=timezone.utc)
        changes.append((t, parse_offset(off)))
    changes.sort(key=lambda x: x[0])

    items = {}
    cats = {}
    for name, sec in pol.items():
        if name.lower().startswith("item:"):
            tname = name[5:].strip()
            items[tname.lower()] = dict(
                name=tname, loan_days=int(sec["loan_days"]), renewals=int(sec["renewals"]),
                grace=int(sec["grace_days"]), daily=cents(sec["daily"]), cap=cents(sec["loan_cap"]))
        elif name.lower().startswith("category:"):
            cname = name[9:].strip()
            cap = sec.get("statement_cap", "none").strip()
            cats[cname.lower()] = dict(
                name=cname, cap=None if cap.lower() == "none" or cap == "" else cents(cap),
                discount=int(sec.get("discount", "0") or 0),
                exempt={x.strip().lower() for x in sec.get("exempt", "").split(",") if x.strip()})

    branches = []
    for r in read_csv(os.path.join(indir, "branches.csv")):
        branches.append((r["branch"], {x for x in r["open_days"].split()}))
    bid = {b.lower(): b for b, _ in branches}
    open_days = {b: od for b, od in branches}

    cal_branch = {}
    cal_star = []
    cal_by_branch = {}
    for r in read_csv(os.path.join(indir, "calendar.csv")):
        ds = r["date"]
        if ".." in ds:
            a, b = ds.split("..", 1)
            first, last = d2(a), d2(b)
        else:
            first = last = d2(ds)
        status = r["status"].strip().lower() == "open"
        br = r["branch"].strip()
        if br == "*":
            cal_star.append((first, last, status))
        else:
            cal_by_branch.setdefault(bid.get(br.lower(), br), []).append((first, last, status))

    open_cache = {}

    def is_open(branch, day):
        key = (branch, day)
        if key in open_cache:
            return open_cache[key]
        res = None
        for first, last, status in cal_by_branch.get(branch, []):
            if first <= day <= last:
                res = status
        if res is None:
            for first, last, status in cal_star:
                if first <= day <= last:
                    res = status
        if res is None:
            res = DAYS[day.weekday()] in open_days.get(branch, set())
        open_cache[key] = res
        return res

    def next_open(branch, day):
        n = 0
        while not is_open(branch, day) and n < 4000:
            day += timedelta(days=1)
            n += 1
        return day

    patron_rows = {}
    for r in read_csv(os.path.join(indir, "patrons.csv")):
        patron_rows.setdefault(pnum(r["patron"]), []).append((d2(r["since"]), r["category"], r["patron"]))
    for v in patron_rows.values():
        v.sort(key=lambda x: x[0])

    def category_on(pn, day):
        best = None
        for since, cat, _ in patron_rows.get(pn, []):
            if since <= day:
                best = cat
        if best is None and patron_rows.get(pn):
            best = patron_rows[pn][0][1]
        return cats[best.lower()]

    # waivers
    waivers = []
    for r in read_csv(os.path.join(indir, "waivers.csv")):
        if r["status"].strip().lower() != "active":
            continue
        v = r["value"].strip()
        waivers.append((pnum(r["patron"]), r["loan"].strip(), None if v.lower() == "full" else cents(v)))

    # events
    def local_dt(at):
        s = at.strip()
        if s.endswith("Z") or s.endswith("z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        dt = dt.astimezone(timezone.utc)
        off = base_off
        for t, o in changes:
            if t <= dt:
                off = o
        return (dt + timedelta(minutes=off)).replace(tzinfo=None)

    events = {}
    exdir = os.path.join(indir, "exports")
    for fn in sorted(os.listdir(exdir)):
        path = os.path.join(exdir, fn)
        if not os.path.isfile(path):
            continue
        recs = []
        if fn.endswith(".csv"):
            for r in read_csv(path):
                if r.get("time"):
                    r["_local"] = datetime.strptime(r["time"], "%Y-%m-%d %H:%M")
                recs.append(r)
        elif fn.endswith(".jsonl"):
            for line in read_text(path).splitlines():
                line = line.strip()
                if not line:
                    continue
                r = json.loads(line)
                r = {k: ("" if v is None else str(v).strip()) for k, v in r.items()}
                if r.get("at"):
                    r["_local"] = local_dt(r["at"])
                recs.append(r)
        else:
            continue
        for r in recs:
            eid = r.get("event", "")
            if eid and eid not in events:
                events[eid] = r

    cancelled = set()
    for e in events.values():
        if e.get("type", "").lower() == "void":
            cancelled.add(e.get("target", ""))

    checkouts = {}
    others = {}
    for eid, e in events.items():
        if eid in cancelled:
            continue
        t = e.get("type", "").lower()
        if t == "checkout":
            checkouts[e["loan"]] = e
        elif t in ("renew", "return"):
            others.setdefault(e["loan"], []).append(e)

    loans = []
    for lid, c in checkouts.items():
        itype = items[c["item_type"].lower()]
        cday = c["_local"].date()
        if cday > pend:
            continue
        branch = bid.get(c["branch"].lower(), c["branch"])
        due = next_open(branch, cday + timedelta(days=itype["loan_days"]))
        renewals = 0
        returned = None
        for e in sorted(others.get(lid, []), key=lambda x: x["_local"]):
            t = e["type"].lower()
            ld = e["_local"].date()
            if t == "renew":
                if ld <= due and renewals < itype["renewals"] and ld <= pend:
                    renewals += 1
                    due = next_open(branch, ld + timedelta(days=itype["loan_days"]))
            else:
                returned = ld - timedelta(days=1) if e.get("via", "").lower() == "dropbox" else ld
                break
        if returned is not None and returned < pstart:
            continue
        out_still = returned is None or returned > pend
        end = pend if out_still else returned
        overdue = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(branch, d):
                overdue += 1
            d += timedelta(days=1)
        if overdue == 0:
            continue
        pn = pnum(c["patron"])
        charged = overdue if overdue > itype["grace"] else 0
        base = charged * itype["daily"]
        cat = category_on(pn, cday)
        if itype["name"].lower() in cat["exempt"] or c["item_type"].lower() in cat["exempt"]:
            base = 0
        base = min(base, itype["cap"])
        assessed = (base * (100 - cat["discount"]) + 50) // 100
        loans.append(dict(
            pn=pn, loan=lid, item=c.get("item", ""), item_type=itype["name"], branch=branch,
            checkout=cday, due=due, returned=None if out_still else returned,
            overdue=overdue, charged=charged, assessed=assessed))

    by_patron = {}
    for l in loans:
        by_patron.setdefault(l["pn"], []).append(l)

    statements = []
    for pn in sorted(by_patron):
        ls = by_patron[pn]
        for l in ls:
            applying = [w for w in waivers if w[0] == pn and w[1] in ("*", l["loan"])]
            if any(w[2] is None for w in applying):
                waived = l["assessed"]
            else:
                waived = min(sum(w[2] for w in applying), l["assessed"])
            l["waived"] = waived
            l["capped"] = 0
        cat = category_on(pn, pend)
        if cat["cap"] is not None:
            excess = sum(l["assessed"] - l["waived"] for l in ls) - cat["cap"]
            if excess > 0:
                order = sorted(ls, key=lambda l: l["loan"], reverse=True)
                order.sort(key=lambda l: l["due"], reverse=True)
                for l in order:
                    if excess <= 0:
                        break
                    take = min(excess, l["assessed"] - l["waived"])
                    l["capped"] = take
                    excess -= take
        ls.sort(key=lambda l: (l["due"], l["loan"]))
        outl = []
        for l in ls:
            l["billed"] = l["assessed"] - l["waived"] - l["capped"]
            outl.append({
                "loan": l["loan"], "item": l["item"], "item_type": l["item_type"], "branch": l["branch"],
                "checkout": l["checkout"].isoformat(), "due": l["due"].isoformat(),
                "returned": l["returned"].isoformat() if l["returned"] else None,
                "overdue_days": l["overdue"], "charged_days": l["charged"],
                "assessed": l["assessed"], "waived": l["waived"], "capped": l["capped"], "billed": l["billed"]})
        pname = patron_rows[pn][-1][2] if pn in patron_rows else ls[0]["pn"]
        stm = {"patron": pname, "category": cat["name"], "loans": outl}
        for k in ("assessed", "waived", "capped", "billed"):
            stm[k] = sum(x[k] for x in outl)
        statements.append(stm)

    bsum = []
    for b, _ in branches:
        row = {"branch": b, "loans": 0, "charged_days": 0, "assessed": 0, "waived": 0, "capped": 0, "billed": 0}
        for s in statements:
            for x in s["loans"]:
                if x["branch"] == b:
                    row["loans"] += 1
                    for k in ("charged_days", "assessed", "waived", "capped", "billed"):
                        row[k] += x[k]
        bsum.append(row)

    result = {"library": library, "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
              "statements": statements, "branches": bsum}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, indent=2, ensure_ascii=False)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
